(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1x = Math.sin(x*0.018+t*0.22)*18 + Math.cos(y*0.013-t*0.17)*12 + Math.sin((x+y)*0.009+t*0.3)*8;
  const warp1y = Math.cos(y*0.02-t*0.2)*18 + Math.sin(x*0.016+t*0.28)*12 + Math.cos((x-y)*0.011-t*0.25)*8;
  const warp2x = Math.sin(warp1x*0.025+t*0.15)*10 + Math.cos(warp1y*0.02-t*0.12)*7;
  const warp2y = Math.cos(warp1y*0.022+t*0.18)*10 + Math.sin(warp1x*0.018-t*0.14)*7;
  const sx = x + warp1x + warp2x, sy = y + warp1y + warp2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.2, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.8, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.5, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.6, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.8, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 2.0, 0.9],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.1, 1.9, 0.85],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*40, 0.075, 2.4, 1.05]
  ];
  let aS = 0, iS = 0, a2 = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const w1 = Math.sin(d*f - t*sp);
    const w2 = Math.sin(d*f*0.618 + t*sp*0.382 + 2.1);
    aS += (w1 + w2*0.5) * w;
    iS += (Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) + Math.sin(d*f*1.3 - t*sp*0.4 + 0.8)*0.4) * w;
    a2 += Math.sin(d*f*0.5 + t*sp*0.3 + Math.atan2(sy-sY, sx-sX)*2) * w * 0.5;
  }
  const tw = 8.48;
  act = aS/tw, inh = iS/tw, harm = a2/tw;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.038+t*1.0))/2;
  const bg2 = Math.sin((sx+sy)*0.1+t*2.2)*0.25 + Math.sin((sx-sy)*0.085-t*1.8)*0.25;
  const bg3 = Math.sin(sx*0.065+t*1.5)*Math.cos(sy*0.055-t*1.2)*0.3;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2-t*1.8)*0.4;
  const spiral = (sp1 + sp2 + sp3)*0.3;
  const ripple = Math.sin(dist*0.08 - t*2.5)*Math.exp(-dist*0.005)*0.3;
  const cellA = Math.sin(sx*0.14)*Math.sin(sy*0.14);
  const cellB = Math.sin((sx+sy)*0.095+t*0.8)*Math.sin((sx-sy)*0.095-t*0.6);
  const cell = Math.tanh((cellA + cellB*0.7)*1.8)*0.25;
  const turb = Math.sin(sx*0.2+sy*0.15+t*3)*Math.sin(sx*0.12-sy*0.18-t*2.5)*0.15;
  const rd1 = act - inh*0.65 + bg*0.25 + spiral*0.35 + ripple + harm*0.2;
  const reaction = Math.tanh(rd1*2.0);
  const blend = reaction*0.65 + cell*0.2 + turb;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[8,28,72],[12,55,95],[18,90,115],
    [35,135,135],[90,175,140],[170,195,110],
    [220,190,70],[235,155,55],[225,110,60],
    [195,70,65],[150,40,55],[95,25,50],[45,15,42],[5,10,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(Math.abs(reaction)*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65 ? 1.12 + (Math.abs(reaction)-0.65)*0.5 : 1.0;
  const vig = 1.0 - Math.pow(dist/320, 2.5)*0.35;
  const m = lum * edge * vig;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
